let rides = {};
let n = 0;
async function order_ride(args) { const id = 'ride-' + (++n); rides[id] = { ...args, status: 'requested' }; return { rideId: id, etaMinutes: 6, price: 18.5 }; }
async function cancel_ride(args) { if (rides[args.rideId]) rides[args.rideId].status = 'cancelled'; return { rideId: args.rideId, cancelled: true }; }
